const STOP_NAME = { 35:'Machined disc pick-up', 45:'Finishing drop-off', 81.5:'Raw casting pick-up', 85:'Pallet pick-up', 95:'Raw casting drop-off', 98.5:'Finished goods drop-off' };
function ringPos(s) {
