];

/* ---------------- Warehouse ---------------- */
const WH = {
  rackX:-29.2, faceX:-26.6, aisle1:-24.6, aisle2:-38, bays:6, levels:3, bayPitch:1.6, levelPitch:1.45,
  standX:-20.3, standFaceX:-22.6, rawStandZ:[9.35, 7.65], fgStandZ:[-7.65, -9.35],
  dockX:-42.2, inboundZ:8, outboundZ:-8, wallX:-46, home:{x:-24.6, z:13.4, yaw:Math.PI},
  forkV:2.2, forkTurn:2.6, forkHandling:10,
  truckQty:8, shipQty:8, reorderPoint:7, shipTrigger:8, truckTravel:30,
};
// rack slots: zone raw on the +z side of the cross aisle, finished goods on the -z side
const SLOTS = [];
for (const zone of ['raw', 'fg']) for (let bay = 0; bay < WH.bays; bay++) for (let level = 0; level < WH.levels; level++) {
  const z = zone === 'raw' ? 3.2 + bay * WH.bayPitch : -3.2 - bay * WH.bayPitch;
  SLOTS.push({id:`${zone === 'raw' ? 'R' : 'F'}-${String(bay + 1).padStart(2, '0')}-${level + 1}`, zone, bay, level, x:WH.rackX, z, y:0.12 + level * WH.levelPitch});
}

const STATE_CODE = {OFF:0, IDLE:1, RUN:2, BLOCKED:3, DOWN:4};
const STATE_LABEL = {RUN:'Running', IDLE:'Waiting for parts', BLOCKED:'Blocked', DOWN:'Down', OFF:'Off'};

/* ---------------- Injected anomalies ---------------- */
// Random process anomalies for monitoring and anomaly-detection demos. Each one shifts process tags of one station
// (or the plant air system); `run` deltas only apply while the station is cycling. Severity scales every effect.
const ANOMALIES = [
  {type:'spindle_bearing', station:'M1', name:'Spindle bearing wear', effect:'Vibration, spindle load and coolant temperature rise; more power per cycle',
   tags:{vibration:[3.2, 'run'], spindleLoad:[14, 'run'], coolantTemp:[4]}, kw:0.25, ct:0.05},
  {type:'coolant_pump', station:'M2', name:'Coolant pump degradation', effect:'Coolant pressure falls, coolant heats up, cycles slow down and more drilling defects',
   tags:{coolantPressure:[-11, 'run'], coolantTemp:[7]}, ct:0.15, defect:0.03},
